function setupLogs(cwd, opts = {}) {
  const force = !!opts.force;
  const steps = [];
  steps.push(ensureMervProperties(cwd, { force, suiteTitle: opts.suiteTitle }));
  steps.push(ensureMervPropertyKey(cwd, "merv.logger.file", "true"));
  steps.push(ensureMervPropertyKey(cwd, "merv.logger.level", "INFO"));
  const { pkg, pkgPath, deps } = packageDeps(cwd);
  if (!pkg) {
    steps.push({
      step: "package.json",
      action: "failed",
      detail: "No package.json in this folder \u2014 run npm init first"
    });
    steps.push({
      step: "next steps",
      action: "skipped",
      detail: "npm init -y && npm i merv-client && npx merv-client doctor setup-log"
    });
    return steps;
  }
  let changed = false;
  const details = [];
  const scripts = { ...pkg.scripts || {} };
  if (!scripts["show-logs"]) {
    scripts["show-logs"] = "merv show-logs";
    changed = true;
    details.push("added show-logs");
  }
  if (!scripts["show-report"]) {
    scripts["show-report"] = "merv show-report";
    changed = true;
    details.push("added show-report");
  }
  const hadMervClient = deps.has("merv-client");
  if (!hadMervClient) {
    pkg.dependencies = {
      ...pkg.dependencies || {},
      "merv-client": "^4.0.25"
    };
    changed = true;
    details.push("added dependency merv-client");
  }
  if (changed) {
    pkg.scripts = scripts;
    writeJsonFile(pkgPath, pkg);
    steps.push({
      step: "package.json",
      action: "updated",
      path: pkgPath,
      detail: `${details.join(", ")} (left other package.json fields unchanged)`
    });
  } else {
    steps.push({
      step: "package.json",
      action: "skipped",
      path: pkgPath,
      detail: "show-logs / show-report / merv-client already present"
    });
  }
  steps.push({
    step: "next steps",
    action: "skipped",
    detail: hadMervClient ? `import { console } from 'merv-client' (or require), then: npx merv show-logs` : `npm install && import { console } from 'merv-client', then: npx merv show-logs`
  });
  return steps;
}
function printLogDoctorResult(steps) {
  printDoctorReport(steps, {
    title: "merv-client doctor setup-log",
    subtitle: "Merv-Logs only \u2014 merv.properties + show-logs (no custom-report / jsconfig)",
    language: "Merv-Logs",
    nextHint: "Full custom report \u2192 npx merv-client doctor setup \xB7 Centralized logs \u2192 https://merv.online/merv-local-centralized-logs.html"
  });
}

